package br.com.luvi.financaspessoais.transferencia.controller;import br.com.luvi.financaspessoais.conta.entity.ContaFinanceira;import br.com.luvi.financaspessoais.conta.service.ContaService;import br.com.luvi.financaspessoais.transferencia.dto.*;import br.com.luvi.financaspessoais.transferencia.service.*;import br.com.luvi.financaspessoais.usuario.service.UsuarioService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;@RestController @RequestMapping("/api/transferencias")public class TransferenciaController{private final TransferenciaService service;private final UsuarioService usuarios;private final ContaService contas;public TransferenciaController(TransferenciaService s,UsuarioService u,ContaService c){service=s;usuarios=u;contas=c;}@PostMapping public TransferenciaResponse criar(@Valid @RequestBody TransferenciaRequest r,Authentication a){return service.criar(r,usuarios.atual(a.getName()));}@GetMapping public List<TransferenciaResponse> listar(@RequestParam int mes,@RequestParam int ano,@RequestParam(required=false)Long contaId,@RequestParam(required=false)Long grupoId,Authentication a){var u=usuarios.atual(a.getName());List<Long>ids;if(contaId!=null){if(!contas.podeAcessar(contaId,u))throw new SecurityException("Conta não permitida.");ids=List.of(contaId);}else if(grupoId!=null)ids=contas.doGrupo(grupoId,u).stream().map(ContaFinanceira::getId).toList();else ids=contas.acessiveis(u).stream().map(ContaFinanceira::getId).toList();YearMonth ym=YearMonth.of(ano,mes);return service.listar(ids,ym.atDay(1),ym.atEndOfMonth());}@DeleteMapping("/{id}")public void excluir(@PathVariable Long id,Authentication a){service.excluir(id,usuarios.atual(a.getName()));}}
